namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace CourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = "CS101", DepartmentId = "cs", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS education pedagogy.", IsFeatured = true },
        new() { Id = "CS201", DepartmentId = "cs", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and competitive programming. He coaches the university's ACM team." },
        new() { Id = "CS301", DepartmentId = "cs", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez spent a decade in industry at major tech companies before joining academia. She specializes in distributed databases." },
        new() { Id = "MATH101", DepartmentId = "math", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Torres", InstructorBio = "Dr. Torres is an award-winning educator known for making calculus accessible and engaging.", IsFeatured = true },
        new() { Id = "MATH202", DepartmentId = "math", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma's research bridges abstract algebra and machine learning applications." },
        new() { Id = "ENG101", DepartmentId = "eng", Title = "Composition & Rhetoric", Description = "Develop clear, persuasive writing skills through essays, research papers, and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing coach who has helped hundreds of students find their voice." },
        new() { Id = "ENG220", DepartmentId = "eng", Title = "American Literature", Description = "Survey of American literary works from the colonial period through the 21st century.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Rachel Green", InstructorBio = "Dr. Green specializes in 20th-century American fiction and has authored two critical anthologies.", IsFeatured = true },
        new() { Id = "PHYS101", DepartmentId = "phys", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Robert Nguyen", InstructorBio = "Dr. Nguyen's research in experimental physics has been published in Nature and Physical Review Letters." },
        new() { Id = "PHYS210", DepartmentId = "phys", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic wave propagation.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM + Fri Lab 1:00–3:00 PM", InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson is a theoretical physicist whose work on electromagnetic modeling has industry applications in antenna design." },
        new() { Id = "HIST101", DepartmentId = "hist", Title = "World History to 1500", Description = "Major civilizations, trade networks, and cultural exchanges from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. Michael Brown", InstructorBio = "Prof. Brown is an archaeologist who has led excavations across the Mediterranean and publishes on ancient trade routes.", IsFeatured = true },
        new() { Id = "HIST205", DepartmentId = "hist", Title = "Modern European History", Description = "Europe from the Enlightenment through the Cold War, focusing on political and social transformations.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Anna Petrov", InstructorBio = "Dr. Petrov emigrated from Eastern Europe and brings firsthand perspective to Cold War and post-Soviet studies." },
    ];

    public List<Department> GetAllDepartments() => Departments;

    public Department? GetDepartment(string id) =>
        Departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => Courses;

    public List<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(string id) =>
        Courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Id.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _submissions = [];

    public void Submit(EnrollmentRequest request)
    {
        _submissions.Add(request);
    }
}

namespace CourseCatalog.Models;

public class Department
